def min_coins_greedy(amount, denominations):
    coins_used = 0
    i = len(denominations) - 1
    while amount > 0:
        while denominations[i] > amount:
            i -= 1
        amount -= denominations[i]
        coins_used += 1
    return coins_used

def min_coins_optimal(amount, denominations):
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0
    for coin in denominations:
        for x in range(coin, amount + 1):
            dp[x] = min(dp[x], dp[x - coin] + 1)
    return dp[amount]

